        "TEST_MODE_MISMATCH" to "Test ortamı ile gerçek işletme karışmaz",
        "TEST_ENV_ONLY" to "Yalnız test ortamında",
        "TEST_RESET_BUSY" to "Sıfırlama bir işlemle çakıştı",
        "TEST_ENV_NESTED" to "Test ortamı gerçek işletmeden açılır",
        "TEST_LIMIT_REACHED" to "Test ortamı dolu",
        "INVALID_KEY" to "Anahtar ayarı geçersiz",
        "BAD_WEBHOOK_URL" to "Webhook adresi kabul edilmedi",
    )

    /** The title of a code, or `null` when the catalogue has none (a code newer than this library). */
    @JvmStatic
    public fun title(code: String?): String? = if (code == null) null else titles[code]
}
